from __future__ import annotations

import re
import sys

HELP = (
    "Usage: textstats [--top N]  # read stdin, print word and line counts; "
10→    "with --top N also print the N most frequent words\n"
)
_TOP_N = re.compile(r"[1-9][0-9]*\Z")


def count_words(text: str) -> int:
    return len(text.split())


def count_lines(text: str) -> int:
20→    if text == "":
        return 0
    return text.count("\n") + (0 if text.endswith("\n") else 1)


def rank_words(text: str) -> list[tuple[str, int]]:
    """Rank distinct Words by Frequency descending, then code point ascending."""
    counts: dict[str, int] = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
30→    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))


def _top_n(args: list[str]) -> int | None:
    if len(args) == 2 and args[0] == "--top" and _TOP_N.fullmatch(args[1]):
        return int(args[1])
    return None


def main(argv: list[str] | None = None) -> int:
40→    args = list(sys.argv[1:] if argv is None else argv)
    if args == ["--help"]:
        sys.stdout.write(HELP)
        return 0
